def investigate(context, acquire):
    hist = acquire("history")
    # Family: put in {ignore, replace, upsert}; trigger in {none, after_insert_log};
    # channel in {changes, total_changes, total_changes_both}.
    # We simulate each candidate and keep those consistent with all receipts.

    def simulate(actions, put_mode, trig, chan):
        # returns (channel_value, committed_count, committed_sum)
        # state: dict key->value for committed; pending per connection
        committed = {}
        # per-connection transaction state: None or dict of pending ops
        # We model writes as applied to a working copy per connection.
        # Simpler: track committed dict, and for each connection an overlay.
        # main and other each have their own view during transaction.
        # Use: base = committed; tx[conn] = dict of key->value or None for delete
        tx = {"main": None, "other": None}
        # working state for a connection: if tx open, overlay on committed
        def view(conn):
            if tx[conn] is None:
                return committed
            d = dict(committed)
            for k, v in tx[conn].items():
                if v is None:
                    d.pop(k, None)
                else:
                    d[k] = v
            return d

        changes = 0
        total_main = 0
        total_other = 0
        log_count = 0

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                if tx[conn] is None:
                    tx[conn] = {}
            elif op == "commit":
                if tx[conn] is not None:
                    for k, v in tx[conn].items():
                        if v is None:
                            committed.pop(k, None)
                        else:
                            committed[k] = v
                    tx[conn] = None
            elif op == "rollback":
                tx[conn] = None
            elif op == "put":
                k = act["key"]
                v = act["value"]
                cur = view(conn)
                existed = k in cur
                if existed:
                    if put_mode == "ignore":
                        # no change
                        pass
                    elif put_mode == "replace":
                        # delete + insert: changes counts 1? Actually REPLACE deletes then inserts -> changes()=1
                        if tx[conn] is None:
                            committed[k] = v
                        else:
                            tx[conn][k] = v
                        changes = 1
                        if conn == "main":
                            total_main += 1
                        else:
                            total_other += 1
                        if trig:
                            log_count += 1
                    else:  # upsert
                        if tx[conn] is None:
                            committed[k] = v
                        else:
                            tx[conn][k] = v
                        changes = 1
                        if conn == "main":
                            total_main += 1
                        else:
                            total_other += 1
                        if trig:
                            log_count += 1
                else:
                    if tx[conn] is None:
                        committed[k] = v
                    else:
                        tx[conn][k] = v
                    changes = 1
                    if conn == "main":
                        total_main += 1
                    else:
                        total_other += 1
                    if trig:
                        log_count += 1
            elif op == "update":
                k = act["key"]
                v = act["value"]
                cur = view(conn)
                if k in cur:
                    if tx[conn] is None:
                        committed[k] = v
                    else:
                        tx[conn][k] = v
                    changes = 1
                    if conn == "main":
                        total_main += 1
                    else:
                        total_other += 1
                    if trig:
                        log_count += 1
            elif op == "delete":
                k = act["key"]
                cur = view(conn)
                if k in cur:
                    if tx[conn] is None:
                        committed.pop(k, None)
                    else:
                        tx[conn][k] = None
                    changes = 1
                    if conn == "main":
                        total_main += 1
                    else:
                        total_other += 1

        if chan == "changes":
            ch = changes
        elif chan == "total_changes":
            ch = total_main
        else:
            ch = total_main + total_other
        return ch, len(committed), sum(committed.values())

    # Determine which candidates are consistent with history
    put_modes = ["ignore", "replace", "upsert"]
    trigs = [False, True]
    chans = ["changes", "total_changes", "total_changes_both"]

    consistent = []
    for pm in put_modes:
        for tg in trigs:
            for ch in chans:
                ok = True
                for rec in hist:
                    acts = rec.get("actions", [])
                    obs = rec.get("observed", {})
                    c, cc, cs = simulate(acts, pm, tg, ch)
                    if c != obs.get("channel") or cc != obs.get("committed_count") or cs != obs.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    consistent.append((pm, tg, ch))

    if not consistent:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    vals = set()
    for pm, tg, ch in consistent:
        c, cc, cs = simulate(actions, pm, tg, ch)
        if goal == "channel":
            vals.add(c)
        elif goal == "committed_count":
            vals.add(cc)
        elif goal == "committed_sum":
            vals.add(cs)
        else:
            return {"value": None, "unresolved": True}
    if len(vals) == 1:
        return {"value": list(vals)[0], "unresolved": False}
    return {"value": None, "unresolved": True}

