def investigate(context, acquire):
    hist = acquire("history")
    # Family: put in {OR IGNORE, OR REPLACE, ON CONFLICT DO UPDATE value}
    # trigger: none or AFTER INSERT log insert
    # channel: changes(), total_changes(main), total_changes(main)+total_changes(other)
    # We must determine which combination is consistent with all receipts,
    # then predict the goal for the query sequence.

    def simulate(put_mode, has_trigger, channel_mode, actions):
        # returns (channel, committed_count, committed_sum)
        # state: dict key->value for committed main db
        # pending transaction state per connection
        committed = {}
        # transaction buffers: None means no open txn
        txn = {"main": None, "other": None}
        # total_changes counters per connection
        tc = {"main": 0, "other": 0}
        # last changes() on main
        last_changes_main = 0
        # trigger log count (unread, but affects total_changes)
        # We'll track total_changes including trigger inserts.

        def apply_put(conn, key, value):
            nonlocal last_changes_main
            # determine current view for this connection
            if txn[conn] is not None:
                view = txn[conn]
            else:
                view = committed
            # simulate insert
            direct = 0
            trig = 0
            if key in view:
                if put_mode == "ignore":
                    direct = 0
                elif put_mode == "replace":
                    view[key] = value
                    direct = 1
                else:  # update
                    view[key] = value
                    direct = 1
            else:
                view[key] = value
                direct = 1
            if direct == 1 and has_trigger:
                trig = 1
            if conn == "main":
                last_changes_main = direct
            tc[conn] += direct + trig

