            nonlocal last_changes_main
            if txn[conn] is not None:
                view = txn[conn]
            else:
                view = committed
            direct = 0
            if key in view:
                view[key] = value
                direct = 1
            if conn == "main":
                last_changes_main = direct
            tc[conn] += direct

        def apply_delete(conn, key):
            nonlocal last_changes_main
            if txn[conn] is not None:
                view = txn[conn]
